  "{@0} Bod $K$ je stred hrany ${@1}$. Vypočítaj vzdialenosť bodov ${@2}$ a $K$ v cm. {@3}": "{@0} 点 $K$ は辺 ${@1}$ の中点です。点 ${@2}$ と $K$ の距離を cm で求めましょう。{@3}",
  "{@0} Funkcia je <strong>{@1}</strong>.": "{@0} この関数は<strong>{@1}</strong>です。",
  "{@0} Normálové vektory sú ${@1}$ a ${@2}$. {@3}": "{@0} 法線ベクトルは ${@1}$ と ${@2}$ です。{@3}",
  "{@0} Normálový vektor roviny ${@1}$ je $\\vec{n}={@2}$ (kolmý na $\\vec{{@3}{@4}}$ aj $\\vec{{@5}{@6}}$), smerový vektor priamky $\\vec{u}={@7}$. $\\vec{u}\\cdot\\vec{n}={@8}$. {@9}": "{@0} 平面 ${@1}$ の法線ベクトルは $\\vec{n}={@2}$（$\\vec{{@3}{@4}}$ にも $\\vec{{@5}{@6}}$ にも垂直）、直線の方向ベクトルは $\\vec{u}={@7}$ です。$\\vec{u}\\cdot\\vec{n}={@8}$。{@9}",
  "{@0} Potom ${@1}{@2}$ a $K{@3}$. $|{@4}K|=\\sqrt{{@5}}=\\sqrt{{@6}}{@7}\\,\\text{cm}$.": "{@0} すると ${@1}{@2}$、$K{@3}$。$|{@4}K|=\\sqrt{{@5}}=\\sqrt{{@6}}{@7}\\,\\text{cm}$。",
  "{@0} Rovina ${@1}$ má normálový vektor $\\vec{n}={@2}$ a rovnicu ${@3}=0$. Pre ${@4}{@5}$: $d=\\dfrac{{@6}}{\\sqrt{{@7}}}\\approx {@8}\\,\\text{cm}$.": "{@0} 平面 ${@1}$ の法線ベクトルは $\\vec{n}={@2}$、方程式は ${@3}=0$ です。${@4}{@5}$ について：$d=\\dfrac{{@6}}{\\sqrt{{@7}}}\\approx {@8}\\,\\text{cm}$。",
  "{@0} Smerový vektor priamky $\\vec{u}=\\vec{{@1}}={@2}$, vektor $\\vec{{@3}{@4}}={@5}$. $d=\\dfrac{|\\vec{{@6}{@7}}\\times\\vec{u}|}{|\\vec{u}|}=\\dfrac{|{@8}|}{\\sqrt{{@9}}}\\approx {@10}\\,\\text{cm}$.": "{@0} 直線の方向ベクトル $\\vec{u}=\\vec{{@1}}={@2}$、ベクトル $\\vec{{@3}{@4}}={@5}$。$d=\\dfrac{|\\vec{{@6}{@7}}\\times\\vec{u}|}{|\\vec{u}|}=\\dfrac{|{@8}|}{\\sqrt{{@9}}}\\approx {@10}\\,\\text{cm}$。",
  "{@0} Správne je ${@1}$, $k\\in\\mathbb{Z}$.": "{@0} 正しくは ${@1}$、$k\\in\\mathbb{Z}$ です。",
  "{@0} Substitúcia $t={@1} x$: ${@2}=0$, korene $t_1={@3}$, $t_2={@4}$. {@5} {@6}. Spolu $K=\\{{@7}\\}$.": "{@0} $t={@1} x$ と置き換えます：${@2}=0$、解は $t_1={@3}$、$t_2={@4}$。{@5} {@6}。合わせて $K=\\{{@7}\\}$。",
  "{@0} Vypočítaj $P(X={@1})$. {@2}": "{@0} $P(X={@1})$ を求めましょう。{@2}",
  "{@0} Vypočítaj $P(X\\ge 1)$. {@1}": "{@0} $P(X\\ge 1)$ を求めましょう。{@1}",
  "{@0} Vypočítaj pravdepodobnosť, že $X\\le 1$. {@1}": "{@0} $X\\le 1$ である確率を求めましょう。{@1}",
  "{@0} Vypočítaj strednú hodnotu $E(X)$ a rozptyl $D(X)$. Zadaj ich v tomto poradí oddelené bodkočiarkou (ako zlomky alebo desatinné čísla zaokrúhlené aspoň na 2 miesta).": "{@0} 期待値 $E(X)$ と分散 $D(X)$ を求めましょう。この順にセミコロンで区切って入力しましょう（分数、または少なくとも小数第 2 位まで四捨五入した小数で）。",
  "{@0} Vypočítaj vzdialenosť vrcholu ${@1}$ od priamky ${@2}$ v cm. {@3}": "{@0} 頂点 ${@1}$ と直線 ${@2}$ の距離を cm で求めましょう。{@3}",
  "{@0} Vypočítaj vzdialenosť vrcholu ${@1}$ od roviny ${@2}$ v cm. {@3}": "{@0} 頂点 ${@1}$ と平面 ${@2}$ の距離を cm で求めましょう。{@3}",
