  "{@0} usporiadaného súboru. Aký je medián?": "{@0}（大きさの順に並べた集団で）。中央値はいくつですか？",
  "{@0} zobrazuje známky z písomky v triede:{@1}Aký je medián známok?": "{@0}はクラスのテストの成績を表しています：{@1}成績の中央値はいくつですか？",
  "{@0} zobrazuje známky z písomky v triede:{@1}Vypočítaj priemernú známku. {@2}": "{@0}はクラスのテストの成績を表しています：{@1}平均の成績を求めましょう。{@2}",
  "{@0} {@1}": "{@0} {@1}",
  "{@0}Zaveď $t={@1} x$, vyrieš kvadratickú rovnicu a ponechaj len korene z intervalu $\\langle -1; 1\\rangle$.": "{@0}$t={@1} x$ と置き換えて 2 次方程式を解き、区間 $\\langle -1; 1\\rangle$ にある解だけを残しましょう。",
  "Údaje najprv usporiadaj podľa veľkosti. Pri párnom počte je medián priemerom dvoch prostredných hodnôt.": "まずデータを大きさの順に並べましょう。個数が偶数のときは、中央値は真ん中の 2 つの値の平均です。",
  "Útvar ohraničený parabolou a priamkou": "放物線と直線で囲まれた図形",
  "Čitateľ ${@0}$ rozlož na súčin ${@1}\\cdot(x+c)$. Aké je číslo $c$?": "分子 ${@0}$ を積 ${@1}\\cdot(x+c)$ に因数分解しましょう。数 $c$ はいくつですか？",
  "Čitateľ derivácie ${@0}({@1})-({@2})\\cdot {@3}$ je po úprave konštanta. Aká?": "導関数の分子 ${@0}({@1})-({@2})\\cdot {@3}$ は、整理すると定数になります。いくつですか？",
  "Čitateľ je nenulová konštanta a menovateľ sa blíži k nule, takže zlomok v absolútnej hodnote rastie nad všetky medze.": "分子は 0 でない定数で、分母は 0 に近づくので、分数の絶対値は限りなく大きくなります。",
  "Čitateľ má nižší stupeň než menovateľ, v čitateli preto zostane len nula a limita je $0$.": "分子の次数が分母より低いので、分子には 0 だけが残り、極限は $0$ です。",
  "Čitateľ zmení znamienko, menovateľ nie: $f(-x)=-f(x)$.": "分子は符号が変わりますが、分母は変わりません：$f(-x)=-f(x)$。",
  "Čitateľa aj menovateľa vydelíme najvyššou mocninou menovateľa, teda ${@0}$. Všetky členy tvaru $\\frac{c}{x^k}$ sa blížia k nule. {@1}": "分子と分母を分母の最高次の累乗、つまり ${@0}$ でわります。$\\frac{c}{x^k}$ の形の項はすべて 0 に近づきます。{@1}",
  "Člen $uv'$ je $({@0})\\cdot\\frac{1}{x}$. Koľko je teda $f'(1)$?": "項 $uv'$ は $({@0})\\cdot\\frac{1}{x}$ です。では、$f'(1)$ はいくつですか？",
  "Číslo $f({@0})$ nie je absolútny člen $q$. Dosaď do $y=f(x_0)+f'(x_0)(x-x_0)$ a roznásob zátvorku.": "数 $f({@0})$ は切片 $q$ ではありません。$y=f(x_0)+f'(x_0)(x-x_0)$ に代入して、かっこを展開しましょう。",
  "Číslo z vodorovnej asymptoty $y=\\dots$ (limita pre $x\\to\\infty$)?": "水平な漸近線 $y=\\dots$ の数（$x\\to\\infty$ の極限）はいくつですか？",
  "Číslo zo zvislej asymptoty $x=\\dots$ (nulový bod menovateľa)?": "垂直な漸近線 $x=\\dots$ の数（分母が 0 になる点）はいくつですか？",
  "čas behu na 100 m": "100 m 走のタイム",
  "čierne": "黒い玉",
  "čiernych": "黒い玉",
  "ľubovoľnú cifru": "どの数字でも",
  "ľubovoľnú cifru okrem nuly": "0 以外のどの数字でも",
  "Žiaci odpovedali, ako chodia do školy:{@0}{@1} Výsledok zaokrúhli na desatiny.": "生徒に、どうやって学校に通っているかを聞きました：{@0}{@1} 結果は小数第 1 位まで四捨五入しましょう。",
  "Žiadny z nich neleží vo vnútri intervalu.": "どれも区間の内部にはありません。",
  "Žiak v teste s {@0} otázkami náhodne tipuje; každá otázka má štyri možnosti a práve jedna je správna. Náhodná premenná $X$ je počet správnych odpovedí.": "{@0} 問のテストで、生徒が当てずっぽうに答えます。どの問題にも選択肢が 4 つあり、正しいのはちょうど 1 つです。確率変数 $X$ は正しい答えの数です。",
  "žiadny reálny koreň": "実数解をもたない",
  "„Najviac jeden“ zahŕňa aj možnosť, že nenastane žiadny úspech. Pripočítaj $P(X=0)$.": "「多くても 1 回」には、成功が 1 回も起こらない場合も含まれます。$P(X=0)$ をたしましょう。",
  "„Najviac jeden“ znamená 0 alebo 1 úspech. Sčítaj tieto dve pravdepodobnosti.": "「多くても 1 回」とは、成功が 0 回または 1 回ということです。この 2 つの確率をたしましょう。"
